    }

    public void reset() {
        comparisons = 0;
        swaps = 0;
        arrayAccesses = 0;
        startTimeNanos = 0;
        endTimeNanos = 0;
    }

    @Override
    public String toString() {
        return String.format(
            "Metrics{comparisons=%d, swaps=%d, accesses=%d, time=%.3f ms}",
            comparisons, swaps, arrayAccesses, getElapsedTimeMillis()
